"""Publication-only renderer. Frozen audited medians -> SVGs and matching HTML tables."""
from pathlib import Path
import json, math, html, hashlib, sys
R=Path(__file__).resolve().parents[1]; L=R.parents[1]/'lab'; A=L/'public/benchmarks/filesystem-automation/assets'
E=['nift','python','node','bun','go']; C=['#b1ff68','#ffbd9a','#d2b4ef','#e9dc91','#88cdb5']; S={}
for p in [R/'work/official',R/'work/filter-suite/work/official']:
 a=json.loads((p/'independent-audit.json').read_text()); assert a['pass'] and json.loads((p/'distribution-audit.json').read_text())['pass']
 assert hashlib.sha256((p/'summary.json').read_bytes()).hexdigest()==a['summary_sha256']
 for x in json.loads((p/'summary.json').read_text()): S[x['scenario'],x['boundary'],x['engine']]=x
M=json.loads((R/'work/orchestration/postexec-memory.json').read_text()); assert M['pass']
mem={(x['files'],x['engine']):x for x in M['rows']}; assert len(mem)==15
for (n,e),x in mem.items(): assert x['correct'] and x['output_sha256']==S[f'walk-{n}','booted',e]['expected_sha256']
meta=json.loads((R/'work/publication-meta.json').read_text()); evidence='https://github.com/nift-experiments/lab-evidence/tree/'+meta['evidence_sha']+'/benchmarks/filesystem-automation/'+meta['series']
sections=[]; plots=[]
def esc(x): return html.escape(str(x))
def panel(id,title,keys,labels,note,unit='ms',memory=False,line=False):
 vals=[[mem[int(k),e]['postexec_vmhwm_mib'] if memory else S.get((k,'booted',e),{}).get('wall_ms',{}).get('median') for e in E] for k in keys]
 sections.append(dict(id=id,title=title,unit=unit,labels=labels,values=vals,scenarios=keys,note=note))
 # All comparisons use explicit logarithmic axes, except diagnostic memory (linear).
 log=not memory; high=max(v for row in vals for v in row if v is not None); low=min(v for row in vals for v in row if v is not None)
 lo=10**math.floor(math.log10(low)) if log else 0; hi=10**math.ceil(math.log10(high)) if log else math.ceil(high/50)*50
 def y(v): return 350-(math.log10(v/lo)/math.log10(hi/lo) if log else v/hi)*260
 svg=['<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 840 440" role="img" aria-labelledby="title desc">',f'<title id="title">{esc(title)}</title><desc id="desc">{esc(note)}. Exact values in the adjacent table. '+('Logarithmic' if log else 'Linear zero-origin')+' vertical axis.</desc>','<rect width="840" height="440" fill="#202622" rx="12"/>',f'<text x="70" y="30" fill="#c3cdc4" font-family="sans-serif" font-size="13">{unit} · '+('LOGARITHMIC SCALE' if log else 'LINEAR SCALE')+'</text>']
 ticks=[10**i for i in range(int(math.log10(lo)),int(math.log10(hi))+1)] if log else list(range(0,int(hi)+1,50))
 for t in ticks:
  yy=y(t); svg.append(f'<path d="M70 {yy}H805" stroke="#3b463d"/><text x="58" y="{yy+4}" text-anchor="end" fill="#b6c0b7" font-family="sans-serif" font-size="12">{t:g}</text>')
 xs=[100+i*660/max(1,len(keys)-1) for i in range(len(keys))] if line else [110+i*680/len(keys) for i in range(len(keys))]
 for j,e in enumerate(E):
  points=[]
  for i,row in enumerate(vals):
   v=row[j]
   if v is None: continue
   xx=xs[i] if line else xs[i]+j*min(22,110/len(keys)); yy=y(v); points.append(f'{xx},{yy}')
   if line: svg.append(f'<circle cx="{xx}" cy="{yy}" r="4.5" fill="{C[j]}"/>')
   else: svg.append(f'<path d="M{xx} 350V{yy}" stroke="{C[j]}" stroke-width="{min(14,72/len(keys))}"/><circle cx="{xx}" cy="{yy}" r="3" fill="{C[j]}"/>')
  if line: svg.append(f'<polyline points="{" ".join(points)}" fill="none" stroke="{C[j]}" stroke-width="2.5"/>')
  xx=80+j*150; svg.append(f'<circle cx="{xx}" cy="410" r="4" fill="{C[j]}"/><text x="{xx+12}" y="414" fill="{C[j]}" font-family="sans-serif" font-size="14">{e.title()}</text>')
 for i,label in enumerate(labels): svg.append(f'<text x="{xs[i] if line else xs[i]+40}" y="377" text-anchor="middle" fill="#dce4dd" font-family="sans-serif" font-size="12">{esc(label)}</text>')
 svg.append('</svg>'); (A/f'{id}.svg').write_text('\n'.join(svg)+'\n'); plots.append(id)
 table=f'<div class="scroll" tabindex="0" role="region" aria-label="{esc(title)} exact values"><table><caption>{esc(title)} · '+('separate post-exec diagnostic, one verified request per cell' if memory else 'booted isolated request, median')+f' · {unit}</caption><thead><tr><th>Workload</th>'+''.join(f'<th>{e.title()}</th>' for e in E)+'</tr></thead><tbody>'
 for label,row in zip(labels,vals): table+='<tr><th>'+esc(label)+'</th>'+''.join('<td>'+('—' if v is None else f'{v:,.3f}')+'</td>' for v in row)+'</tr>'
 table+='</tbody></table></div>'
 return f'<div class="measurement"><figure><div class="chart-scroll" tabindex="0" role="region" aria-label="Scrollable graph"><img src="@path(\'public/benchmarks/filesystem-automation/assets/{id}.svg\')" alt="{esc(title)}" width="840" height="440"></div><figcaption>{esc(note)} '+('Linear zero-origin axis.' if memory else 'Logarithmic axis; equal vertical steps represent multiplicative changes.' + ('' if line else ' Bars start at the displayed positive minimum, not zero.'))+f' <a href="@path(\'public/benchmarks/filesystem-automation/assets/{id}.svg\')">SVG ↗</a></figcaption></figure>{table}<p class="scroll-hint">Exact values above. On small screens, scroll the table independently →</p></div>'
parts=[]
def sec(id,num,title,lede,body): parts.append(f'<section id="{id}" class="inspection"><div class="section-label"><span>{num}</span><code>project/{id}/</code></div><div class="section-body"><h2>{title}</h2><p class="lede">{lede}</p>{body}</div></section>')
def gap(ratio,description): return f'<aside class="finding"><strong>{ratio}</strong><p>{description}</p></aside>'
sec('walk','01','Follow every path.','A directory walk becomes a runtime workload long before it becomes a bandwidth test.',gap('52×','At 10k files: Nift 1,349.687 ms versus Bun 25.833 ms. The same checked path inventory, on this node.')+panel('walk','Traversal scaling',[f'walk-{n}' for n in [1000,10000,100000]],['1k files','10k files','100k files'],'Five runtimes enumerate the same three-level fixture and return a verified path inventory',line=True))
sec('inspect','02','Metadata has a cost.','Type-only checks acquire size metadata too. The explicit stat workload adds two queries per file.',gap('45×','At 10k files: Nift 3,054.717 ms versus Bun 68.224 ms.')+panel('stat','Metadata scaling',[f'stat-{n}' for n in [1000,10000,100000]],['1k files','10k files','100k files'],'Exists/type/size inspection, with checked metadata inventories',line=True)+'''<div class="syscalls"><h3>One tree. Repeated metadata queries.</h3><div><span>Logical files</span><b>10,000</b><i style="width:24.17%"></i></div><div><span>Walk: newfstatat</span><b>21,373</b><i style="width:51.66%"></i></div><div><span>Stat: newfstatat</span><b>41,373</b><i style="width:100%"></i></div><p>Separate traced Nift requests; linear zero-origin counts. Counts include directory/runtime work. Only four readlinks per trace. Syscall counts do not explain all wall time.</p></div>''')
sec('select','03','Inspect first. Select second.','Every filter stats every file before selection. Selection percentages describe results, not avoided metadata work.',panel('select','Filtering / 10k files',['filter-1-10000','filter-10-10000','filter-50-10000','filter-extension-10000','filter-prefix-10000','filter-size-10000'],['Name 1%','Name 10%','Name 50%','Extension','Prefix','Size'],'Extension .md selects 20%; group00 prefix 5%; size ≥768 bytes 40%. Extension/group/size are correlated'))
sec('read','04','Small files expose scalar work.','The checksum visits every byte in the language. Large-file reads load the full payload but aggregate endpoints only.',gap('65×','10k small-file read + checksum: Nift 13,950.634 ms versus Go 213.459 ms.')+panel('read','Small-file read + checksum',[f'read-{n}' for n in [1000,10000,100000]],['1k files','10k files','100k files'],'Portable h=(31h+byte)%1000000007 checksum; noncryptographic; output inventories included',line=True)+panel('large-read','100 MiB bulk-read contrast',['large-read-10x10485760','large-read-100x1048576'],['10 × 10 MiB','100 × 1 MiB'],'These different contracts isolate a bulk-read contrast, not a subtraction-based estimate of checksum cost'))
sec('fingerprint','05','A fingerprint is not a security digest.','Native SHA-256 is unavailable in this Nift snapshot. The portable checksum cannot substitute for a cryptographic release manifest.',panel('hash','Native SHA-256 / 10k files',['hash-sha256-10000'],['SHA-256'],'— means unavailable; it is not zero or a failed observation'))
sec('write','06','Create. Overwrite. Copy.','Stream writes include source reads; copies verify bytes and paths, not permissions or metadata.',gap('10×','100k-file copy: Nift 59,348.510 ms versus Go 5,805.511 ms.')+panel('write','Write and copy',['write-10000','overwrite-10000','large-write-10x10485760','large-write-100x1048576','copy-100000'],['Create 10k','Overwrite 10k','10 × 10 MiB','100 × 1 MiB','Copy 100k'],'Small stream writes, existing-file overwrite, 100 MiB streams, and a 100k-file copy are distinct contracts'))
sec('mirror','07','Unchanged still means inspected.','Both trees are fingerprinted. Identical destination files retain their timestamps.',gap('57×','Clean 10k mirror: Nift 28,734.412 ms versus Go 507.798 ms.')+'''<div class="diff"><div><h3>source/</h3><code>  keep.md <span>unchanged</span><br>~ edit.md <span>new bytes</span><br>+ add.dat <span>new path</span></code></div><div><h3>destination/ → reconciled</h3><code>  keep.md <span>preserve mtime</span><br>~ edit.md <span>replace bytes</span><br>+ add.dat <span>copy</span><br>- old.dat <span>remove</span></code></div></div>'''+panel('mirror','Mirror / 10k files',[f'mirror-{v}-10000' for v in [0,1,10,11,12]],['Clean','1% content','10% content','Mixed','Add/delete'],'Mixed =10% content +1% add/delete; add/delete-only =1% replacement paths. Diagram illustrates semantics, not a measured individual filename'))
sec('changes','08','What changed depends on the contract.','Modification-time access is unavailable in this Nift snapshot. Content and timestamp detection intentionally answer different questions.',panel('changes','Change detection / 10k files',[f'detect-{kind}-{v}-10000' for kind in ['mtime','hash'] for v in [1,2,3]],['Time: bytes','Time: time','Time: restored','Hash: bytes','Hash: time','Hash: restored'],'Same 1% selected set: changed bytes/new time; same bytes/new time; changed bytes/restored time. Time-only detection misses restored-time edits; content ignores time-only edits'))
sec('pipeline','09','The project, end to end.','Generate documents, copy selected assets and produce a sorted manifest. This is controlled project automation, not a website build.',gap('28×','Mixed 10k workflow: Nift 8,552.832 ms versus Go 300.728 ms.')+panel('pipeline','Project workflows / 10k files',['manifest-10000','generate-10000','mixed-10000'],['Manifest','Generate','Mixed'],'Manifest =path/size/portable fingerprint; generate prefixes inputs; mixed ignores group19, generates .md and copies .dat. Traversal still visits ignored paths'))
sec('memory','10','Measure the runtime after exec.','The official wait4 RSS contains an inherited supervisor-image floor. It cannot rank runtime memory efficiency.',panel('memory','Post-exec walk high-water mark',['1000','10000','100000'],['1k files','10k files','100k files'],'Separate /proc VmHWM diagnostic; one independently verified request per runtime/size, not official distributions',unit='MiB',memory=True,line=True)+'<p>A true-child control rose from 8.395 to 72.492 MiB when the parent allocated 64 MiB, despite doing no runtime workload. Frozen raw RSS is retained unchanged; no constant has been subtracted.</p>')
sec('diagnostics','11','Where Nift spends the work.','Profiles point to both filesystem-specific amplification and a busy scalar/value execution path.', '''<div class="priorities"><article><small>P0 · CORRECTNESS</small><h3>One call must mean one call.</h3><p>The read-loop <code>execute(...).stringify()</code> reduction prints CALLED three times; binding the result prints it once. Accepted adapters use the checked safe binding. This is a serious core defect, not an accepted benchmark failure.</p></article><article><small>P1 · METADATA</small><h3>Reuse what the tree already knows.</h3><p>The inspector queries status and file size even for type-only checks. Extra 20,000 stat calls accompany the 10k explicit-stat workload. Preserve races, symlinks and error contracts when consolidating.</p></article><article><small>P1 · ALLOCATION</small><h3>5,578,191 allocations.</h3><p>The separate 10k stat heaptrack diagnostic records 1,111,623 temporary allocations. String construction and condition trimming are concrete leads; instrumentation changes timing.</p></article><article><small>P1/P2 · SCALAR</small><h3>Bytes become evaluator work.</h3><p>Read profiles include AST evaluation, RuntimeValue lifetime, loop dispatch and variable lookup. Bulk reads are far less extreme. This motivates decomposition, not a claim that one function explains the gap.</p></article></div><p>Template Engines also profiled expression/string/allocation work; Concurrency profiled AST/value handling while demonstrating real multicore scaling. A shared value/execution mechanism is plausible, but their differing paths do not establish a single root cause.</p>''')
sec('practitioner','12','Would I choose it?','Usable for bounded Nift-owned automation; large-tree throughput is weak in this snapshot.', '''<p>For new filesystem or release tooling today, I would choose Python for compact library-driven automation or Go for a maintained standalone utility. Traversal overhead, repeated metadata queries, allocation volume, slow per-byte interpreter work and copy/mirror costs are operational problems. Missing timestamps, native cryptographic hashing and clear recursive cleanup add real contract gaps. Exactly-once side-effect reliability takes priority over speed.</p><h3>What would change my preference?</h3><p>Reusable metadata-bearing directory entries; fewer status/size queries; substantially less path/string/value allocation; faster scalar processing; native SHA-256 and timestamps; safe recursive helpers; repaired chained-call evaluation; and competitive large-tree scaling. I would retain explicit roots, artifact ownership, lifecycle and independently checkable outputs.</p><div class="scroll" tabindex="0" role="region" aria-label="Present and mature Nift preferences"><table class="verdict"><caption>Qualitative preference · present day versus a reliable, capable, competitive Nift</caption><thead><tr><th>Workflow</th><th>Today</th><th>Mature-Nift counterfactual</th></tr></thead><tbody><tr><th>Nift-owned project</th><td>Nift for bounded covered operations</td><td>Nift: shared policy and lifecycle</td></tr><tr><th>Agent-authored automation</th><td>Python/Go for a new filesystem tool</td><td>Nift: programmable explicit contracts, without another executor underneath</td></tr><tr><th>New release tooling</th><td>Python/Go: hashes, timestamps, cleanup</td><td>Nift for project-attached release policy; Go for standalone delivery</td></tr><tr><th>Large tree scanner</th><td>Go: throughput and typed metadata/errors</td><td>Nift becomes viable if scaling and memory are genuinely competitive</td></tr><tr><th>Portable standalone utility</th><td>Go: compiled binary, no installed script runtime</td><td>Still often Go: build/distribute per-platform binaries with embedded dependencies</td></tr></tbody></table></div><p>Existing Python or JS module requirements remain specific integration reasons to choose those runtimes. This Linux campaign does not certify Windows paths, symlinks or portability. Explicitness is useful only when the runtime reliably enforces it.</p>''')
sec('method','13','Frozen evidence. Open interpretation.','No measurements, adapters or diagnostics were changed to produce this redesign.',f'''<p>{esc(meta['machine'])} Four-CPU affinity. {esc(meta['counts'])}</p><p>Fresh timing includes launch and exit; booted timing begins after readiness and ends at the complete response. Every observation uses a new runtime. Fixtures are restored, fully read and statted outside timing. Runtime order rotates; no outliers are removed. Full result sets/output SHA-256 checks and independent distribution/reset audits pass. Low-count stress tails are descriptive.</p><p>Warm Linux filesystem state, ASCII paths, fixed three-level corpus, no symlink/permission/glob or physical-bandwidth claim. Five file sizes (96–2,048 bytes) and extensions correlate with groups. No fsync or global cache dropping. Output serialization is inside timing; canonical oracle sorting is outside (Nift ls itself sorts).</p><details><summary>Frozen identities / timing tails / implementation boundaries</summary><p>Primary <code>999defe8dae3f9d15e9a17225e6014020be04574</code>; supplement <code>5af31b2036046009c11411fe72f6193c3febf057</code>; core <code>445f4d3545cf031bcce4bf77a2b4a61ffb3b4c4f</code>. Evidence commit <code>{meta['evidence_sha']}</code>.</p><p>All 752 distributions, p95/min/max, commands, source, correctness and implementation boundaries remain in the evidence and full appendix. The launch/lifetime memory accounting limitation is preserved alongside the corrected diagnostic.</p></details><p><a href="{evidence}">Canonical frozen evidence ↗</a> · <a href="https://github.com/nift-experiments/filesystem-automation/blob/main/docs/RESULTS.md">Complete distributions ↗</a> · <a href="https://github.com/nift-experiments/filesystem-automation/blob/main/docs/NIFT-CORE-HANDOVER.md">Core handover ↗</a></p>''')
hero='''<main id="main"><header class="hero"><div class="hero-copy"><p class="eyebrow">EXPERIMENT 08 / FILESYSTEM AUTOMATION</p><h1>Every file.<br>Every consequence.</h1><p class="intro">A project tree under inspection.<br>Five runtimes. One verified filesystem.</p><p class="hero-verdict">Nift completes the work.<br><strong>Large-tree throughput is not competitive.</strong></p><a class="open" href="#walk">Inspect the findings ↓</a></div><div class="inspector"><div class="window-bar"><span>◉ project/</span><span>READ · VERIFY · RECONCILE</span></div><div class="tree-map"><div class="folder">▾ project/</div><div class="branch">▾ group00/ … group19/<div class="branch">▾ depth0/ … depth2/<div class="branch">▾ bucket000/<p><code>f000000.md</code><em>GENERATE</em></p><p><code>f000001.json</code><em>INSPECT</em></p><p><code>f000004.dat</code><em>COPY</em></p></div></div></div><div class="manifest">↳ output/manifest.tsv <span>✓ VERIFIED</span></div></div><div class="density"><span>1,000</span><i>→</i><span>10,000</span><i>→</i><span>100,000 files</span></div></div></header><div class="pipeline-trail" aria-label="Workload pipeline"><span>SCAN</span>→<span>INSPECT</span>→<span>SELECT</span>→<span>READ</span>→<span>HASH</span>→<span>TRANSFORM</span>→<span>WRITE</span></div><p class="participants">Nift 4.11.0 snapshot · Python 3.15.0 · Node 24.21.0 · Bun 1.4.3 · Go 1.27.2</p><nav class="index" aria-label="Report sections">'''+''.join(f'<a href="#{id}">{title}</a>' for id,title in [('walk','walk'),('inspect','inspect'),('select','select'),('read','read'),('mirror','mirror'),('pipeline','pipeline'),('memory','memory'),('diagnostics','diagnostics'),('practitioner','verdict')])+ '</nav>'
(L/'content/benchmarks/filesystem-automation/index.html').write_text(hero+'\n'.join(parts)+'</main>\n')
(A/'published.json').write_text(json.dumps({'meta':meta,'sections':sections},separators=(',',':'))+'\n')
print(f'{len(plots)} SVG charts; {sum(len(s["values"]) for s in sections)} exact-value rows')
